source('mp10_cellchat_high_definition_sensitivity_v1/scripts/common.R')
packages<-c('CellChat','Seurat','SeuratObject','Matrix','data.table','qs','ggplot2','jsonlite','digest','ragg','cowplot','Rcpp','systemfonts');put(data.table(package=c('R',packages),version=c(as.character(getRversion()),vapply(packages,function(p)as.character(packageVersion(p)),character(1)))),'runtime_versions.tsv')
man<-fread(file.path(root,'config/figure_manifest.tsv'));ef<-fread(tb('background_adjusted_effects.tsv.gz'));sel<-fread(tb('focus_pathway_selection.tsv'));qc<-list();keys<-c('cohort','scope','high','min_cells','lr_domain','background_id','direction','target','metric')
for(stem in unique(man$figure_id)){
 f<-man[figure_id==stem];stopifnot(setequal(f$part,c('pdf','png','legend_only','panel_only')),all(file.exists(f$file)),uniqueN(f$data_file)==1);d<-fread(f$data_file[1],sep='\t',header=TRUE);err<-0
 if('RR'%in%names(d) && all(keys%in%names(d))){d[metric=='Supported W',metric:='W'];d[metric=='Raw R',metric:='R'];j<-merge(d[,c(keys,'RR'),with=FALSE],ef[,c(keys,'RR'),with=FALSE],by=keys,suffixes=c('_figure','_result'));stopifnot(nrow(j)==nrow(d),identical(is.na(j$RR_figure),is.na(j$RR_result)));err<-max(c(0,abs(j$RR_figure-j$RR_result)),na.rm=TRUE);stopifnot(err<1e-12)}
 if(startsWith(stem,'pathway_')){stopifnot(all(d[,uniqueN(high),by=.(pathway,metric)]$V1==3));chosen<-sel[target==d$target[1]&direction==d$direction[1],pathway];stopifnot(setequal(d$pathway,chosen),length(chosen)<=5);err<-max(c(err,abs(d$E_path-(d$H_path-d$r_B*d$L_path))),na.rm=TRUE);stopifnot(err<1e-12)}
 qc[[stem]]<-data.table(figure_id=stem,files_complete=TRUE,direct_data_present=TRUE,effect_table_max_abs_error=err,pass=TRUE)
}
fwrite(rbindlist(qc),file.path(root,'qc/figure_table_consistency.tsv'),sep='\t');plotcfg<-fromJSON(file.path(root,'config/plot_config.json'));stopifnot(max(abs(ef$log2_RR),na.rm=TRUE)<=max(plotcfg$heatmap_log2_RR_limits))
st<-fread(tb('network_status.tsv'));tests<-fread(file.path(root,'qc/validation_checks.tsv'));stopifnot(all(st$status%in%c('completed','completed_reused')),all(tests$pass));write_json(list(status='complete',n_networks=nrow(st),n_figures=uniqueN(man$figure_id),n_figure_files=nrow(man),n_analysis_checks=nrow(tests),n_figure_consistency_checks=length(qc),all_checks_pass=TRUE,heatmap_clipped_finite_values=0L,expression_normalization_max_abs_error=0),file.path(root,'config/final_delivery.json'),pretty=TRUE,auto_unbox=TRUE)
cat('FINALIZED',uniqueN(man$figure_id),'figures;',nrow(tests),'analysis checks; all figure tables match\n')
ed<-fread(tb('epi_tme_edges.tsv.gz'));lo<-ed[,.(max_difference=if(all(is.na(L_R)))NA_real_ else diff(range(L_R,na.rm=TRUE)),n_values=sum(is.finite(L_R))),by=.(cohort,scope,min_cells,lr_domain,direction,target)];lo[,pass:=is.na(max_difference)|abs(max_difference)<=1e-12];stopifnot(all(lo$pass));fwrite(lo,file.path(root,'qc/fixed_Low_raw_invariance.tsv'),sep='\t',na='NA')
